"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { Bell, GitPullRequest, MessageSquare, Sparkles } from "lucide-react";
import { type ReactNode, useId, useRef, useState } from "react";
import { twMerge } from "tailwind-merge";

import {
  slideVariants,
  spring,
  staggerContainer,
  withReducedMotion,
} from "@/lib/motion-tokens";
import { surfaceClasses } from "@/lib/surface-classes";
import { SurfaceProvider } from "@/lib/surface-context";
import { Badge } from "@/components/matos-ui/badge";
import { Button } from "@/components/matos-ui/button";
import { Elevated } from "@/components/matos-ui/elevated";

type Note = {
  id: string;
  icon: ReactNode;
  title: string;
  body: string;
  time: string;
  unread: boolean;
};

const SEED: Note[] = [
  {
    id: "n-1",
    icon: <GitPullRequest className="size-4" aria-hidden="true" />,
    title: "Review requested on #4821",
    body: "Priya opened “Tune the morph tier for wide surfaces”.",
    time: "2m",
    unread: true,
  },
  {
    id: "n-2",
    icon: <MessageSquare className="size-4" aria-hidden="true" />,
    title: "New reply in #design-system",
    body: "“Shipping the elevation ladder doc today — final pass now.”",
    time: "18m",
    unread: true,
  },
  {
    id: "n-3",
    icon: <Sparkles className="size-4" aria-hidden="true" />,
    title: "Deploy succeeded",
    body: "matos-ui.com is live at build 2f7c1a in 41s.",
    time: "1h",
    unread: false,
  },
];

const EXTRA: Omit<Note, "id" | "unread"> = {
  icon: <Bell className="size-4" aria-hidden="true" />,
  title: "Weekly digest is ready",
  body: "3 merged PRs, 12 issues closed, 1 release cut.",
  time: "now",
};

/**
 * A notification centre built on the Surfaces system.
 *
 * The panel is the app background (level 1). Every card is an `Elevated`
 * `offset={1}`, so it reads one rung above the panel in light and dark alike,
 * and lifts another shadow step under the cursor via `hoverLift`.
 *
 * The list is a real `staggerContainer`: cards arrive on `slideVariants("top")`
 * one after another. A new notification pushes in at the top on the same
 * variant; a dismissal plays its exit (slide out, `spring.slow.exit`) before
 * `layout` closes the gap. Under `prefers-reduced-motion` every card still
 * crossfades in and out — nothing travels.
 */
export function NotificationCenter01() {
  const reduce = !!useReducedMotion();
  const idBase = useId();
  const [notes, setNotes] = useState<Note[]>(SEED);
  const addedRef = useRef(0);

  const unread = notes.filter((n) => n.unread).length;
  const enter = slideVariants("top", { distance: 18, tier: spring.moderate });
  const item = reduce ? withReducedMotion(enter) : enter;

  function add() {
    addedRef.current += 1;
    setNotes((current) => [
      { ...EXTRA, id: `${idBase}-x${addedRef.current}`, unread: true },
      ...current,
    ]);
  }

  function dismiss(id: string) {
    setNotes((current) => current.filter((n) => n.id !== id));
  }

  function markAllRead() {
    setNotes((current) => current.map((n) => ({ ...n, unread: false })));
  }

  return (
    <SurfaceProvider value={1}>
      <div
        data-slot="notification-center-01"
        className={twMerge(
          "@container/notif w-full max-w-md rounded-2xl p-3 text-foreground",
          surfaceClasses(1),
        )}
      >
        <div className="mb-2 flex flex-wrap items-center justify-between gap-2 px-1">
          <div className="flex items-center gap-2">
            <span className="font-semibold text-sm tracking-tight">
              Notifications
            </span>
            {unread > 0 ? (
              <Badge variant="secondary" size="sm" className="tabular-nums">
                {unread} new
              </Badge>
            ) : null}
          </div>
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="sm"
              onClick={markAllRead}
              disabled={unread === 0}
            >
              Mark all read
            </Button>
            <Button variant="outline" size="sm" onClick={add}>
              Simulate
            </Button>
          </div>
        </div>

        <motion.ul
          className="flex flex-col gap-2 px-1 pb-1"
          variants={staggerContainer("moderate")}
          initial="hidden"
          animate="visible"
        >
          <AnimatePresence initial={false} mode="popLayout">
            {notes.map((note) => (
              <motion.li
                key={note.id}
                layout={!reduce}
                variants={item}
                exit={
                  reduce
                    ? { opacity: 0 }
                    : { opacity: 0, x: 44, transition: spring.slow.exit }
                }
                transition={{ layout: spring.moderate }}
              >
                <Elevated
                  offset={1}
                  hoverLift
                  className="flex items-start gap-3 rounded-xl p-3"
                >
                  <span
                    className={twMerge(
                      "mt-0.5 grid size-8 shrink-0 place-items-center rounded-lg",
                      note.unread
                        ? "bg-primary/12 text-primary"
                        : "bg-muted text-muted-foreground",
                    )}
                  >
                    {note.icon}
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                      <p className="truncate font-medium text-foreground text-sm">
                        {note.title}
                      </p>
                      {note.unread ? (
                        <>
                          <span className="sr-only">Unread</span>
                          <span
                            aria-hidden="true"
                            className="size-1.5 shrink-0 rounded-full bg-primary"
                          />
                        </>
                      ) : null}
                      <span className="ml-auto shrink-0 text-[11px] text-muted-foreground tabular-nums">
                        {note.time}
                      </span>
                    </div>
                    <p className="mt-0.5 line-clamp-2 text-muted-foreground text-xs leading-relaxed">
                      {note.body}
                    </p>
                  </div>
                  <Button
                    variant="ghost"
                    size="icon-sm"
                    aria-label={`Dismiss “${note.title}”`}
                    className="-mr-1 -mt-1 shrink-0"
                    onClick={() => dismiss(note.id)}
                  >
                    <span aria-hidden="true" className="text-base leading-none">
                      ×
                    </span>
                  </Button>
                </Elevated>
              </motion.li>
            ))}
          </AnimatePresence>

          {notes.length === 0 ? (
            <motion.li
              initial={reduce ? false : { opacity: 0 }}
              animate={{ opacity: 1 }}
              className="rounded-xl border border-border/60 border-dashed py-8 text-center text-muted-foreground text-xs"
            >
              You&rsquo;re all caught up.
            </motion.li>
          ) : null}
        </motion.ul>
      </div>
    </SurfaceProvider>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  ArrowRight,
  CornerDownLeft,
  FileText,
  LayoutDashboard,
  Plus,
  Search,
  Settings,
  UserPlus,
} from "lucide-react";
import { type ReactNode, useMemo, useState } from "react";
import { twMerge } from "tailwind-merge";

import {
  directionalVariants,
  liftVariants,
  spring,
  staggerContainer,
  withReducedMotion,
} from "@/lib/motion-tokens";
import { surfaceClasses } from "@/lib/surface-classes";
import { SurfaceProvider } from "@/lib/surface-context";
import { Elevated } from "@/components/matos-ui/elevated";

// The palette panel animates its entrance *and* sits on the elevation ladder,
// so it has to be a motion element and an `Elevated` at once — wrapping one in
// the other would add a layout box. Same reason for the moving highlight below.
const MotionElevated = motion.create(Elevated);

type Command = {
  id: string;
  label: string;
  hint: string;
  icon: ReactNode;
  group: "Actions" | "Go to";
};

const COMMANDS: Command[] = [
  {
    id: "new-project",
    label: "Create project",
    hint: "P",
    icon: <Plus className="size-4" aria-hidden="true" />,
    group: "Actions",
  },
  {
    id: "invite",
    label: "Invite teammate",
    hint: "I",
    icon: <UserPlus className="size-4" aria-hidden="true" />,
    group: "Actions",
  },
  {
    id: "new-doc",
    label: "New document",
    hint: "D",
    icon: <FileText className="size-4" aria-hidden="true" />,
    group: "Actions",
  },
  {
    id: "dashboard",
    label: "Dashboard",
    hint: "G D",
    icon: <LayoutDashboard className="size-4" aria-hidden="true" />,
    group: "Go to",
  },
  {
    id: "settings",
    label: "Settings",
    hint: "G S",
    icon: <Settings className="size-4" aria-hidden="true" />,
    group: "Go to",
  },
];

/**
 * A command palette that spells out the Surfaces composition rule.
 *
 * The frame is the app background (level 1). The palette is an `Elevated`
 * `offset={4}` — the conventional dialog offset — so it resolves to surface-5
 * over a dimmed scrim. The highlighted row is a second `Elevated`, `offset={1}`
 * *inside* the palette, so it lands at surface-6: a popover-weight surface
 * nested in a dialog-weight one, each reading its own substrate, in light and
 * dark. Hover and arrow keys slide that highlight between rows on the `fast`
 * tier (a shared `layoutId`, the same move `ui/motion-tabs` makes), the rows
 * stagger in fast on `liftVariants(2)` — a result list is a menu, not the
 * panel — and the panel itself enters with `directionalVariants("bottom")`.
 *
 * Under `prefers-reduced-motion` the panel crossfades, the rows crossfade in
 * place, and the highlight jumps rather than slides.
 */
export function CommandMenu01() {
  const reduce = !!useReducedMotion();
  const [open, setOpen] = useState(true);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    return q
      ? COMMANDS.filter((command) => command.label.toLowerCase().includes(q))
      : COMMANDS;
  }, [query]);

  const groups = useMemo(() => {
    const map = new Map<Command["group"], Command[]>();
    for (const command of results) {
      const list = map.get(command.group) ?? [];
      list.push(command);
      map.set(command.group, list);
    }
    return [...map.entries()];
  }, [results]);

  const clampedActive = Math.min(active, Math.max(0, results.length - 1));
  const panelEnter = directionalVariants("bottom", spring.slow);

  function move(delta: number) {
    if (results.length === 0) return;
    setActive((current) => {
      const base = Math.min(current, results.length - 1);
      return (base + delta + results.length) % results.length;
    });
  }

  return (
    <SurfaceProvider value={1}>
      <div
        data-slot="command-menu-01"
        className={twMerge(
          "@container/cmd relative w-full overflow-hidden rounded-2xl p-4 text-foreground",
          surfaceClasses(1),
        )}
      >
        {/* A hint of the app underneath, so the scrim and the lift read. */}
        <div aria-hidden="true" className="space-y-2 opacity-60">
          <div className="h-2.5 w-1/3 rounded-full bg-muted" />
          <div className="h-2 w-2/3 rounded-full bg-muted/70" />
          <div className="h-2 w-1/2 rounded-full bg-muted/70" />
        </div>

        <div className="pointer-events-none flex min-h-[19rem] items-start justify-center pt-6">
          <button
            type="button"
            aria-hidden="true"
            tabIndex={-1}
            onClick={() => setOpen(false)}
            className={twMerge(
              "absolute inset-0 bg-foreground/8 transition-opacity",
              open ? "opacity-100" : "pointer-events-none opacity-0",
            )}
          />

          <AnimatePresence initial={false}>
            {open ? (
              <MotionElevated
                key="palette"
                offset={4}
                tabIndex={0}
                role="listbox"
                aria-label="Command palette"
                variants={reduce ? withReducedMotion(panelEnter) : panelEnter}
                initial="hidden"
                animate="visible"
                exit={
                  reduce
                    ? { opacity: 0 }
                    : { opacity: 0, y: 8, transition: spring.slow.exit }
                }
                onKeyDown={(event) => {
                  if (event.key === "ArrowDown") {
                    event.preventDefault();
                    move(1);
                  } else if (event.key === "ArrowUp") {
                    event.preventDefault();
                    move(-1);
                  } else if (event.key === "Escape") {
                    setOpen(false);
                  }
                }}
                className="pointer-events-auto relative z-10 w-full max-w-md overflow-hidden rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <div className="flex items-center gap-2.5 border-border/60 border-b px-3.5 py-3">
                  <Search
                    className="size-4 shrink-0 text-muted-foreground"
                    aria-hidden="true"
                  />
                  <input
                    autoComplete="off"
                    spellCheck={false}
                    value={query}
                    onChange={(event) => {
                      setQuery(event.target.value);
                      setActive(0);
                    }}
                    placeholder="Type a command or search…"
                    aria-label="Search commands"
                    className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
                  />
                  <kbd className="rounded border border-border/70 bg-muted px-1.5 py-0.5 font-mono text-[10px] text-muted-foreground">
                    ⌘K
                  </kbd>
                </div>

                <motion.div
                  className="max-h-64 space-y-3 overflow-y-auto p-2"
                  variants={staggerContainer("fast", reduce ? 0 : 0.03)}
                  initial="hidden"
                  animate="visible"
                >
                  {groups.map(([group, items]) => (
                    <div key={group}>
                      <p className="px-2 pb-1 font-medium text-[11px] text-muted-foreground uppercase tracking-widest">
                        {group}
                      </p>
                      <div className="space-y-0.5">
                        {items.map((command) => {
                          const index = results.indexOf(command);
                          const isActive = index === clampedActive;
                          return (
                            <motion.button
                              key={command.id}
                              type="button"
                              role="option"
                              aria-selected={isActive}
                              variants={
                                reduce
                                  ? withReducedMotion(liftVariants(2))
                                  : liftVariants(2)
                              }
                              onMouseEnter={() => setActive(index)}
                              onFocus={() => setActive(index)}
                              className="relative flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left text-sm outline-none"
                            >
                              {isActive ? (
                                <MotionElevated
                                  layoutId="command-active"
                                  offset={1}
                                  aria-hidden="true"
                                  transition={
                                    reduce ? { duration: 0 } : spring.fast
                                  }
                                  className="pointer-events-none absolute inset-0 rounded-lg"
                                />
                              ) : null}
                              <span
                                className={twMerge(
                                  "relative z-10 shrink-0",
                                  isActive
                                    ? "text-primary"
                                    : "text-muted-foreground",
                                )}
                              >
                                {command.icon}
                              </span>
                              <span className="relative z-10 min-w-0 flex-1 truncate text-foreground">
                                {command.label}
                              </span>
                              <kbd className="relative z-10 shrink-0 font-mono text-[11px] text-muted-foreground">
                                {command.hint}
                              </kbd>
                            </motion.button>
                          );
                        })}
                      </div>
                    </div>
                  ))}

                  {results.length === 0 ? (
                    <p className="px-3 py-6 text-center text-muted-foreground text-sm">
                      No commands match &ldquo;{query}&rdquo;.
                    </p>
                  ) : null}
                </motion.div>

                <div className="flex items-center justify-between border-border/60 border-t px-3.5 py-2 text-[11px] text-muted-foreground">
                  <span className="flex items-center gap-1">
                    <CornerDownLeft className="size-3" aria-hidden="true" />
                    to run
                  </span>
                  <span className="flex items-center gap-1">
                    <span className="font-mono">↑ ↓</span> to navigate
                  </span>
                </div>
              </MotionElevated>
            ) : (
              <motion.button
                key="trigger"
                type="button"
                initial={reduce ? false : { opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                onClick={() => setOpen(true)}
                className="pointer-events-auto relative z-10 flex items-center gap-2 rounded-full border border-border bg-surface-2 px-4 py-2 text-muted-foreground text-sm shadow-surface-2 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
              >
                <Search className="size-4" aria-hidden="true" />
                Open command menu
                <ArrowRight className="size-3.5" aria-hidden="true" />
              </motion.button>
            )}
          </AnimatePresence>
        </div>
      </div>
    </SurfaceProvider>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { Check } from "lucide-react";
import { useState } from "react";
import { twMerge } from "tailwind-merge";

import {
  revealVariants,
  spring,
  staggerContainer,
  withReducedMotion,
} from "@/lib/motion-tokens";
import { surfaceClasses } from "@/lib/surface-classes";
import { SurfaceProvider } from "@/lib/surface-context";
import { Badge } from "@/components/matos-ui/badge";
import { Button } from "@/components/matos-ui/button";
import { Elevated } from "@/components/matos-ui/elevated";

type Billing = "monthly" | "annual";

type Tier = {
  id: string;
  name: string;
  blurb: string;
  monthly: number;
  annual: number;
  offset: 1 | 2;
  featured?: boolean;
  cta: string;
  features: string[];
};

const TIERS: Tier[] = [
  {
    id: "starter",
    name: "Starter",
    blurb: "For a side project finding its shape.",
    monthly: 0,
    annual: 0,
    offset: 1,
    cta: "Start free",
    features: ["1 workspace", "Community support", "7-day history"],
  },
  {
    id: "pro",
    name: "Pro",
    blurb: "For a team shipping every week.",
    monthly: 19,
    annual: 15,
    offset: 2,
    featured: true,
    cta: "Choose Pro",
    features: [
      "Unlimited workspaces",
      "Priority support",
      "Unlimited history",
      "Audit log",
    ],
  },
  {
    id: "team",
    name: "Team",
    blurb: "For an org that needs the controls.",
    monthly: 49,
    annual: 39,
    offset: 1,
    cta: "Choose Team",
    features: ["SSO & SCIM", "Roles & permissions", "Dedicated success"],
  },
];

/**
 * A pricing table that puts the elevation ladder to work.
 *
 * The section is the page background (level 1). The two outer tiers are
 * `Elevated` `offset={1}`; the featured tier is `offset={2}`, so it sits a full
 * rung higher than its neighbours — raised by fill in dark mode and by shadow
 * in light, with no fixed background anywhere. All three lift another step
 * under the cursor via `hoverLift`.
 *
 * The billing toggle is a shared-`layoutId` pill on the `moderate` tier; each
 * price swaps on a short slide keyed to the billing choice. The grid reveals on
 * scroll with `revealVariants` + a `staggerContainer`, and every one of those
 * is dropped to a plain crossfade under `prefers-reduced-motion`.
 */
export function PricingTiers01() {
  const reduce = !!useReducedMotion();
  const [billing, setBilling] = useState<Billing>("monthly");

  const card = revealVariants({ y: 16, blur: 4 });
  const cardVariant = reduce ? withReducedMotion(card) : card;

  return (
    <SurfaceProvider value={1}>
      <section
        data-slot="pricing-tiers-01"
        className={twMerge(
          "@container/pricing w-full rounded-2xl p-5 text-foreground @xl/pricing:p-8",
          surfaceClasses(1),
        )}
      >
        <div className="mx-auto flex max-w-md flex-col items-center text-center">
          <h2 className="font-semibold text-2xl tracking-tight">
            Priced to grow with you
          </h2>
          <p className="mt-2 text-muted-foreground text-sm leading-relaxed">
            Every plan reads its own surface. Switch billing and only the number
            moves.
          </p>

          <div className="mt-5 flex items-center gap-1 rounded-full border border-border/60 bg-muted/50 p-1">
            <span className="sr-only">Billing period</span>
            {(["monthly", "annual"] as const).map((period) => {
              const isActive = billing === period;
              return (
                <button
                  key={period}
                  type="button"
                  aria-pressed={isActive}
                  onClick={() => setBilling(period)}
                  className={twMerge(
                    "relative rounded-full px-3.5 py-1.5 font-medium text-xs capitalize outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring",
                    isActive ? "text-foreground" : "text-muted-foreground",
                  )}
                >
                  {isActive ? (
                    <motion.span
                      layoutId="pricing-billing-pill"
                      aria-hidden="true"
                      transition={reduce ? { duration: 0 } : spring.moderate}
                      className="absolute inset-0 rounded-full border border-border bg-background shadow-xs"
                    />
                  ) : null}
                  <span className="relative z-10">{period}</span>
                  {period === "annual" ? (
                    <span className="relative z-10 ml-1.5 text-[10px] text-primary">
                      -20%
                    </span>
                  ) : null}
                </button>
              );
            })}
          </div>
        </div>

        <motion.div
          className="mx-auto mt-8 grid max-w-5xl gap-4 @2xl/pricing:grid-cols-3 @2xl/pricing:items-start"
          variants={staggerContainer("slow")}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-80px" }}
        >
          {TIERS.map((tier) => {
            const price = billing === "monthly" ? tier.monthly : tier.annual;
            return (
              <motion.div key={tier.id} variants={cardVariant}>
                <Elevated
                  offset={tier.offset}
                  hoverLift
                  className={twMerge(
                    "flex h-full flex-col gap-5 rounded-2xl p-5",
                    tier.featured &&
                      "ring-1 ring-primary/25 @2xl/pricing:-translate-y-2",
                  )}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <p className="font-semibold text-base tracking-tight">
                        {tier.name}
                      </p>
                      <p className="mt-1 text-muted-foreground text-xs leading-relaxed">
                        {tier.blurb}
                      </p>
                    </div>
                    {tier.featured ? (
                      <Badge variant="secondary" size="sm" dot pulse>
                        Popular
                      </Badge>
                    ) : null}
                  </div>

                  <div className="flex items-end gap-1">
                    <span className="text-muted-foreground text-sm">$</span>
                    <div className="relative h-9 overflow-hidden">
                      <AnimatePresence mode="popLayout" initial={false}>
                        <motion.span
                          key={price}
                          initial={
                            reduce ? { opacity: 0 } : { opacity: 0, y: 14 }
                          }
                          animate={{ opacity: 1, y: 0 }}
                          exit={
                            reduce
                              ? { opacity: 0 }
                              : {
                                  opacity: 0,
                                  y: -14,
                                  transition: spring.fast.exit,
                                }
                          }
                          transition={
                            reduce ? { duration: 0.12 } : spring.moderate
                          }
                          className="block font-semibold text-3xl tabular-nums tracking-tight"
                        >
                          {price}
                        </motion.span>
                      </AnimatePresence>
                    </div>
                    <span className="pb-1 text-muted-foreground text-xs">
                      / mo
                    </span>
                  </div>

                  <ul className="flex-1 space-y-2">
                    {tier.features.map((feature) => (
                      <li
                        key={feature}
                        className="flex items-start gap-2 text-sm"
                      >
                        <Check
                          className="mt-0.5 size-3.5 shrink-0 text-primary"
                          aria-hidden="true"
                        />
                        <span className="text-muted-foreground">{feature}</span>
                      </li>
                    ))}
                  </ul>

                  <Button
                    variant={tier.featured ? "default" : "outline"}
                    className="w-full"
                  >
                    {tier.cta}
                  </Button>
                </Elevated>
              </motion.div>
            );
          })}
        </motion.div>
      </section>
    </SurfaceProvider>
  );
}

"use client";

import { motion, useInView, useReducedMotion } from "framer-motion";
import { TrendingDown, TrendingUp } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { twMerge } from "tailwind-merge";

import {
  ease,
  revealVariants,
  staggerContainer,
  withReducedMotion,
} from "@/lib/motion-tokens";
import { surfaceClasses } from "@/lib/surface-classes";
import { SurfaceProvider } from "@/lib/surface-context";
import { Elevated } from "@/components/matos-ui/elevated";

type Stat = {
  id: string;
  label: string;
  value: number;
  format: (value: number) => string;
  delta: number;
  series: number[];
};

const STATS: Stat[] = [
  {
    id: "mrr",
    label: "MRR",
    value: 48200,
    format: (value) => `$${(value / 1000).toFixed(1)}k`,
    delta: 12.4,
    series: [12, 14, 13, 17, 16, 21, 20, 24, 27, 26, 31, 34],
  },
  {
    id: "active",
    label: "Active teams",
    value: 1284,
    format: (value) => Math.round(value).toLocaleString("en-US"),
    delta: 6.1,
    series: [40, 42, 41, 45, 47, 46, 50, 53, 52, 58, 61, 64],
  },
  {
    id: "churn",
    label: "Churn",
    value: 1.8,
    format: (value) => `${value.toFixed(1)}%`,
    delta: -0.4,
    series: [30, 28, 29, 26, 24, 25, 22, 21, 19, 20, 17, 15],
  },
  {
    id: "nps",
    label: "NPS",
    value: 62,
    format: (value) => Math.round(value).toString(),
    delta: 3.0,
    series: [44, 45, 48, 47, 50, 52, 51, 55, 57, 56, 60, 62],
  },
];

const COUNT_MS = 900;

function useCountUp(target: number, run: boolean, reduce: boolean) {
  const [value, setValue] = useState(reduce ? target : 0);

  useEffect(() => {
    if (!run) return;
    if (reduce) {
      setValue(target);
      return;
    }
    let frame = 0;
    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / COUNT_MS);
      // ease.decelerate, sampled — fast in, soft landing, same curve the
      // reveal uses so the number and the card settle together.
      const eased = 1 - (1 - t) ** 3;
      setValue(target * eased);
      if (t < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [target, run, reduce]);

  return value;
}

/** Normalises a series into an SVG polyline that fills a 0..w / 0..h box. */
function sparkPoints(series: number[], width: number, height: number) {
  const min = Math.min(...series);
  const max = Math.max(...series);
  const span = max - min || 1;
  return series
    .map((point, index) => {
      const x = (index / (series.length - 1)) * width;
      const y = height - ((point - min) / span) * height;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");
}

function Tile({ stat, inView }: { stat: Stat; inView: boolean }) {
  const reduce = !!useReducedMotion();
  const value = useCountUp(stat.value, inView, reduce);
  const up = stat.delta >= 0;
  const points = sparkPoints(stat.series, 96, 28);

  return (
    <Elevated
      offset={1}
      hoverLift
      className="flex flex-col gap-3 rounded-xl p-4"
    >
      <div className="flex items-center justify-between gap-2">
        <span className="font-mono text-[11px] text-muted-foreground uppercase tracking-widest">
          {stat.label}
        </span>
        <span
          className={twMerge(
            "flex items-center gap-0.5 font-medium text-[11px] tabular-nums",
            up ? "text-primary" : "text-muted-foreground",
          )}
        >
          {up ? (
            <TrendingUp className="size-3" aria-hidden="true" />
          ) : (
            <TrendingDown className="size-3" aria-hidden="true" />
          )}
          {up ? "+" : ""}
          {stat.delta.toFixed(1)}%
        </span>
      </div>

      <p className="font-semibold text-2xl tabular-nums tracking-tight">
        {stat.format(value)}
      </p>

      <svg
        viewBox="0 0 96 28"
        preserveAspectRatio="none"
        className="h-7 w-full text-primary/70"
        aria-hidden="true"
      >
        <motion.polyline
          points={points}
          fill="none"
          stroke="currentColor"
          strokeWidth={1.75}
          strokeLinecap="round"
          strokeLinejoin="round"
          initial={reduce ? false : { pathLength: 0, opacity: 0 }}
          animate={
            inView
              ? { pathLength: 1, opacity: 1 }
              : { pathLength: 0, opacity: 0 }
          }
          transition={{ duration: 0.7, ease: ease.decelerate }}
        />
      </svg>
    </Elevated>
  );
}

/**
 * A row of KPI tiles that reads its substrate and animates once, on scroll.
 *
 * The panel is the app background (level 1); each tile is an `Elevated`
 * `offset={1}` that lifts a further shadow step under the cursor. The grid
 * reveals with `revealVariants` + a `staggerContainer`, the numbers count up on
 * the same `decelerate` curve as the reveal, and each sparkline draws itself
 * in. `useInView` fires the whole thing once; `prefers-reduced-motion` lands
 * every tile, number and line at its final state with no travel.
 */
export function StatTiles01() {
  const reduce = !!useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { once: true, margin: "-80px" });

  const tile = revealVariants({ y: 16, blur: 4 });
  const tileVariant = reduce ? withReducedMotion(tile) : tile;

  return (
    <SurfaceProvider value={1}>
      <div
        ref={ref}
        data-slot="stat-tiles-01"
        className={twMerge(
          "@container/stats w-full rounded-2xl p-4 text-foreground",
          surfaceClasses(1),
        )}
      >
        <motion.div
          className="grid gap-3 @md/stats:grid-cols-2 @3xl/stats:grid-cols-4"
          variants={staggerContainer("moderate")}
          initial="hidden"
          animate={inView ? "visible" : "hidden"}
        >
          {STATS.map((stat) => (
            <motion.div key={stat.id} variants={tileVariant}>
              <Tile stat={stat} inView={inView} />
            </motion.div>
          ))}
        </motion.div>
      </div>
    </SurfaceProvider>
  );
}

