                  <Camera aria-hidden="true" />
                  Change photo
                </Button>
              </section>

              <div className="grid gap-4 @xl/settings:grid-cols-2">
                <InputField
                  id={`${formId}-name`}
                  label="Full name"
                  autoComplete="name"
                  value={name}
                  onChange={(event) => {
                    setName(event.target.value);
                    markDirty();
                  }}
                  reserveMessageSpace={false}
                  disabled={isSaving}
                />
                <InputField
                  id={`${formId}-role`}
                  label="Role"
                  value={role}
                  onChange={(event) => {
                    setRole(event.target.value);
                    markDirty();
                  }}
                  reserveMessageSpace={false}
                  disabled={isSaving}
                />
              </div>

              <InputField
                id={`${formId}-email`}
                type="email"
                label="Email address"
                autoComplete="email"
                value={email}
                onChange={(event) => {
                  setEmail(event.target.value);
                  setEmailError(null);
                  markDirty();
                }}
                error={emailError ?? undefined}
                trailing={<Mail className="size-4" />}
                reserveMessageSpace={Boolean(emailError)}
                disabled={isSaving}
              />

              <TextareaField
                id={`${formId}-bio`}
                label="Bio"
                value={bio}
                maxLength={160}
                onChange={(event) => {
                  setBio(event.target.value);
                  markDirty();
                }}
                description={`${bio.length}/160 characters`}
                reserveMessageSpace={false}
                disabled={isSaving}
              />
            </div>

            <footer className="flex flex-col gap-3 border-border border-t bg-muted/35 p-4 @sm/settings:flex-row @sm/settings:items-center @sm/settings:justify-between @2xl/settings:px-5">
              <output
                aria-live="polite"
                className="min-h-5 text-xs text-muted-foreground"
              >
                {status === "saved"
                  ? "Your profile changes have been saved."
                  : "Changes are visible to workspace members."}
              </output>
              <div className="flex gap-2">
                <Button
                  type="button"
                  variant="ghost"
                  className="h-11 flex-1 @sm/settings:h-9 @sm/settings:flex-none"
                  disabled={isSaving}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  className="h-11 flex-1 @sm/settings:h-9 @sm/settings:flex-none"
                  loading={isSaving}
                  loadingText="Saving…"
                >
                  Save changes
                </Button>
              </div>
            </footer>
          </form>
        </div>
      </div>
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ChevronDown } from "lucide-react";
import { useState } from "react";
import { twMerge } from "tailwind-merge";

import { Badge } from "@/components/matos-ui/badge";
import { Elevated } from "@/components/matos-ui/elevated";
import type { NavGroup } from "../data";

export type NavSectionProps = {
  group: NavGroup;
  activeId: string;
  onSelect: (id: string) => void;
};

const itemBase =
  "group/nav flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring";

export function NavSection({ group, activeId, onSelect }: NavSectionProps) {
  const shouldReduceMotion = useReducedMotion();
  const [open, setOpen] = useState(true);

  return (
    <div data-slot="nav-section" className="space-y-1">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
        className="flex w-full items-center justify-between gap-2 rounded-md px-2.5 py-1 text-[11px] font-medium uppercase tracking-widest text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
      >
        {group.label}
        <ChevronDown
          className={twMerge(
            "size-3.5 transition-transform duration-200",
            open ? "rotate-0" : "-rotate-90",
          )}
          aria-hidden="true"
        />
      </button>

      <AnimatePresence initial={false}>
        {open ? (
          <motion.ul
            key="items"
            initial={
              shouldReduceMotion ? { opacity: 1 } : { height: 0, opacity: 0 }
            }
            animate={
              shouldReduceMotion
                ? { opacity: 1 }
                : { height: "auto", opacity: 1 }
            }
            exit={
              shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }
            }
            transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }}
            className="space-y-0.5 overflow-hidden"
          >
            {group.items.map((item) => {
              const Icon = item.icon;
              const active = item.id === activeId;

              const inner = (
                <>
                  <Icon
                    className={twMerge(
                      "size-4 shrink-0 transition-colors",
                      active
                        ? "text-foreground"
                        : "text-muted-foreground group-hover/nav:text-foreground",
                    )}
                    aria-hidden="true"
                  />
                  <span className="min-w-0 flex-1 truncate text-left">
                    {item.label}
                  </span>
                  {item.badge ? (
                    <Badge variant="count" size="xs" aria-hidden="true">
                      {item.badge}
                    </Badge>
                  ) : null}
                </>
              );

              return (
                <li key={item.id}>
                  {active ? (
                    // Active item lifts one step off the sidebar substrate.
                    <Elevated offset={1} shadowLevel={2} className="rounded-lg">
                      <button
                        type="button"
                        aria-current="page"
                        onClick={() => onSelect(item.id)}
                        className={twMerge(itemBase, "text-foreground")}
                      >
                        {inner}
                      </button>
                    </Elevated>
                  ) : (
                    <button
                      type="button"
                      onClick={() => onSelect(item.id)}
                      className={twMerge(
                        itemBase,
                        "text-muted-foreground hover:bg-surface-3 hover:text-foreground",
                      )}
                    >
                      {inner}
                    </button>
                  )}
                </li>
              );
            })}
          </motion.ul>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ChevronsUpDown, LogOut, Settings, UserRound } from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { Elevated } from "@/components/matos-ui/elevated";
import { currentUser } from "../data";

const menuItems = [
  { id: "profile", label: "Profile", icon: UserRound },
  { id: "settings", label: "Account settings", icon: Settings },
];

export function UserMenu() {
  const shouldReduceMotion = useReducedMotion();
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) {
      return;
    }

    function handlePointerDown(event: PointerEvent) {
      if (rootRef.current && !rootRef.current.contains(event.target as Node)) {
        setOpen(false);
      }
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    // Move focus into the menu when it opens.
    menuRef.current
      ?.querySelector<HTMLButtonElement>("[role='menuitem']")
      ?.focus();

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [open]);

  return (
    <div ref={rootRef} data-slot="user-menu" className="relative">
      <AnimatePresence>
        {open ? (
          <motion.div
            initial={
              shouldReduceMotion
                ? { opacity: 0 }
                : { opacity: 0, y: 6, scale: 0.98 }
            }
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={
              shouldReduceMotion
                ? { opacity: 0 }
                : { opacity: 0, y: 4, scale: 0.98 }
            }
            transition={{ duration: 0.16, ease: [0.22, 1, 0.36, 1] }}
            className="absolute bottom-[calc(100%+0.5rem)] left-0 right-0 z-20"
          >
            {/* Popover lifts two steps off the sidebar substrate, with a
                constant popover shadow regardless of nesting depth. */}
            <Elevated
              offset={2}
              shadowLevel={4}
              className="overflow-hidden rounded-xl p-1"
            >
              <div ref={menuRef} role="menu" aria-label="Account">
                {menuItems.map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    role="menuitem"
                    onClick={() => setOpen(false)}
                    className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm text-foreground outline-none transition-colors hover:bg-surface-5 focus-visible:bg-surface-5 focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    <item.icon
                      className="size-4 text-muted-foreground"
                      aria-hidden="true"
                    />
                    {item.label}
                  </button>
                ))}
                <div className="my-1 h-px bg-border" />
                <button
                  type="button"
                  role="menuitem"
                  onClick={() => setOpen(false)}
                  className="flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm text-destructive outline-none transition-colors hover:bg-destructive/10 focus-visible:bg-destructive/10 focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <LogOut className="size-4" aria-hidden="true" />
                  Sign out
                </button>
              </div>
            </Elevated>
          </motion.div>
        ) : null}
      </AnimatePresence>

      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
        className="flex w-full items-center gap-2.5 rounded-xl bg-surface-1 px-2 py-2 text-left shadow-surface-1 outline-none transition-colors hover:bg-surface-3 focus-visible:ring-2 focus-visible:ring-ring"
      >
        <span
          aria-hidden="true"
          className="grid size-8 shrink-0 place-items-center rounded-lg bg-primary text-xs font-semibold text-primary-foreground"
        >
          {currentUser.initials}
        </span>
        <span className="min-w-0 flex-1">
          <span className="block truncate text-sm font-medium text-foreground">
            {currentUser.name}
          </span>
          <span className="block truncate text-xs text-muted-foreground">
            {currentUser.email}
          </span>
        </span>
        <ChevronsUpDown
          className="size-4 shrink-0 text-muted-foreground"
          aria-hidden="true"
        />
      </button>
    </div>
  );
}

